schemaSql:
CREATE TABLE shop_customers (
  id INTEGER PRIMARY KEY,
  name TEXT
);

CREATE TABLE shop_orders (
  id INTEGER PRIMARY KEY,
  customer_id INTEGER
);

startingSql:
SELECT name
FROM shop_customers
WHERE id NOT IN (SELECT customer_id FROM shop_orders);

solutionSql:
SELECT c.name
FROM shop_customers c
WHERE NOT EXISTS (SELECT 1 FROM shop_orders o WHERE o.customer_id = c.id);
